// Original quasi-static rigid lever. No notebook or persistence operations.
export const leverPivots=Object.freeze([1,2,3]);
export const leverArms=r=>leverPivots.includes(r)?{load:12/(r+1),push:12*r/(r+1)}:null;
const prefix=[[12,12,9],[12,6,9],[6,3,9],[6,2,9],[12,4,9],[6,6,6]],all=[];
for(const weight of[6,12])for(const capacity of[2,3,4,6,12])for(const space of[6,8,9])if(leverPivots.some(r=>leverArms(r).push<=space&&weight/r<=capacity))all.push([weight,capacity,space]);
export const leverCases=Object.freeze([...prefix,...all.filter(t=>!prefix.some(p=>p.every((n,i)=>n===t[i])))].map(([weight,capacity,space])=>Object.freeze({weight,capacity,space})));
const freshWork=()=>({pivot:1,draft:1,drop:0,started:false,delivered:false,turn:'plan',notice:null});
export const freshLeverYard=()=>({offset:0,current:0,page:'work',works:Array.from({length:6},freshWork)});
export const leverJob=(s,i=s.current)=>Number.isInteger(i)&&i>=0&&i<6?leverCases[(s.offset+i)%17]:null;
export function leverView(s){const work=s.works[s.current],job=leverJob(s),pivot=work.turn==='plan'?work.draft:work.pivot,arms=leverArms(pivot),drop=work.started&&pivot===work.pivot?work.drop:0,force=job.weight/pivot;return {work,job,pivot,arms,drop,force,rise:drop/pivot,energy:force*drop,fullWork:force*pivot,space:arms.push<=job.space,capacity:force<=job.capacity,planned:work.turn==='plan',done:work.started&&work.drop===work.pivot,count:s.works.filter(w=>w.delivered).length};}
export function changeLever(s,a,value){
 if(!s)return null;
 if(a==='pivot'&&!leverPivots.includes(value)||a==='job'&&(!Number.isInteger(value)||value<0||value>=6))return null;
 const v=leverView(s),w=v.work,n={...s,works:s.works.map(x=>({...x}))},q=n.works[n.current];
 if(a==='pivot'&&w.turn==='plan'){q.draft=value;q.notice=null;}
 else if(a==='start'&&w.turn==='plan'){if(!v.space)q.notice='space';else if(!v.capacity)q.notice='force';else{if(!w.started||w.draft!==w.pivot)q.drop=0;q.pivot=w.draft;q.started=true;q.turn='push';q.notice=null;}}
 else if(a==='plan'&&w.started){q.turn='plan';q.draft=w.pivot;q.notice=null;}
 else if(a==='keep'&&w.started){q.turn='push';q.draft=w.pivot;q.notice=null;}
 else if(a==='push'&&w.started&&w.turn==='push'&&w.drop<w.pivot&&v.space&&v.capacity){q.drop++;if(q.drop===q.pivot)q.delivered=true;}
 else if(a==='bottom'&&w.started){q.drop=0;q.notice=null;}
 else if(a==='jobs')n.page='jobs';else if(a==='return')n.page='work';
 else if(a==='job'){n.current=value;n.page='work';}
 else if(a==='next'&&v.done){const i=Array.from({length:6},(_,i)=>(s.current+i+1)%6).find(i=>!s.works[i].delivered);if(i===undefined)n.page='jobs';else{n.current=i;n.page='work';}}
 else if(a==='shift'&&v.count===6)return {...freshLeverYard(),offset:(s.offset+6)%17};
 else return null;return n;
}
export function leverGeometry(r,d){const arms=leverArms(r);if(!arms||!Number.isFinite(d)||d<0||d>r)return null;const angle=Math.asin(d/arms.push),u={x:Math.cos(angle),y:-Math.sin(angle)},n={x:Math.sin(angle),y:Math.cos(angle)},p={x:380,y:145},e={x:p.x-40*arms.push*u.x,y:p.y-40*arms.push*u.y},t={x:p.x+40*arms.load*u.x,y:p.y+40*arms.load*u.y};return {arms,angle,u,n,p,e,t,c:{x:t.x,y:t.y+28},start:{x:380-40*arms.push,y:145},pushLabel:{x:(p.x+e.x)/2-30*n.x,y:(p.y+e.y)/2-30*n.y},loadLabel:{x:(p.x+t.x)/2-30*n.x,y:(p.y+t.y)/2-30*n.y}};}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,t,extra='')=>`<button type="button" data-lever-action="${a}" ${extra}>${esc(t)}</button>`;
const fraction=(d,r)=>d===0?'0':d===r?'1':`${d}/${r}`;
const point=p=>`${p.x},${p.y}`;
function poseParts(g){const {e,t,n,p,start}=g,corner=(p,k)=>({x:p.x+k*n.x,y:p.y+k*n.y});return {pole:[corner(e,4),corner(t,4),corner(t,-4),corner(e,-4)].map(point).join(' '),line:`M${point(e)}L${point(t)}`,hanger:`M${point(t)}v12`,arrow:`M${e.x} ${e.y+12}V${e.y+32}M${e.x-5} ${e.y+26}L${e.x} ${e.y+32}L${e.x+5} ${e.y+26}`,arc:e.y>145?`M${point(start)}A${40*g.arms.push} ${40*g.arms.push} 0 0 0 ${point(e)}`:'',bracket:e.y>145?`M3 145V${e.y}M1 145H5M1 ${e.y}H5`:''};}
export function leverDrawing(v){const g=leverGeometry(v.pivot,v.drop),q=poseParts(g);return `<svg data-lever-drawing viewBox="0 0 740 350" role="img" aria-labelledby="lever-picture-title lever-picture-desc"><title id="lever-picture-title">A rigid lever lifting a delivery</title><desc id="lever-picture-desc">Same twelve meter pole. Push arm ${v.arms.push} meters, load arm ${v.arms.load} meters. Fixed pivot. Vertical push drop ${v.drop} of ${v.pivot} meters; load rise ${fraction(v.drop,v.pivot)} meter. Calculated vertical push ${v.force} newtons. Curved path length is not the work distance.</desc><rect width="740" height="350" fill="#d8eaf2"/><path d="M0 251Q140 225 265 251T480 249T740 253V350H0Z" fill="#cbdcc5"/><path d="M160 47h62m185 17h66" stroke="#fffdf5" stroke-width="10" stroke-linecap="round" opacity=".8"/><rect data-lever-ground x="0" y="300" width="740" height="50" fill="#bfd2bd"/><path data-lever-space d="M${380-40*v.job.space} 270V300" stroke="#7d6e46" stroke-width="1.5" stroke-dasharray="4 4"/>
 <path data-lever-end-path d="${q.arc}" fill="none" stroke="#716742" stroke-width="1.5" stroke-dasharray="3 4"/><path data-lever-drop-bracket d="${q.bracket}" fill="none" stroke="#516c65" stroke-width="1.5"/>
 <polygon data-lever-support points="380,145 356,300 404,300" fill="#c5a161" stroke="#79663f" stroke-width="1.5"/><polygon data-lever-pole points="${q.pole}" fill="${v.space?'#c5a161':'#f2eddc'}" stroke="#79663f" stroke-width="1.5" ${v.space?'':'stroke-dasharray="7 4"'}/><path data-lever-centreline d="${q.line}" fill="none" stroke="#183f39" stroke-width="1"/><circle data-lever-pin cx="380" cy="145" r="5" fill="#183f39"/>
 <circle data-lever-handle cx="${g.e.x}" cy="${g.e.y}" r="8" fill="#fffdf5" stroke="#183f39" stroke-width="2"/><path data-lever-push-arrow d="${q.arrow}" fill="none" stroke="#b2572e" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
 <path data-lever-hanger d="${q.hanger}" fill="none" stroke="#9b6f2d" stroke-width="2"/><g data-lever-load transform="translate(${g.c.x} ${g.c.y})"><circle r="16" fill="#c5a161" stroke="#183f39" stroke-width="2"/><path d="M-9-12V12M9-12V12" stroke="#79663f"/><text class="ll-weight" y="4" text-anchor="middle">${v.job.weight} N</text></g>
 <text data-lever-arm-label="push" x="${g.pushLabel.x}" y="${g.pushLabel.y}" text-anchor="middle">Push arm ${v.arms.push} m</text><text data-lever-arm-label="load" x="${g.loadLabel.x}" y="${g.loadLabel.y}" text-anchor="middle">Load arm ${v.arms.load} m</text><text x="380" y="328" text-anchor="middle">Fixed pivot</text>
 <path data-lever-rise d="M650 133V173M645 133H655M645 173H655" fill="none" stroke="#183f39" stroke-width="1.5"/><text x="646" y="208" text-anchor="end">1 m rise</text><g aria-hidden="true"><text x="734" y="27" text-anchor="end">Push needed (N)</text><rect x="700" y="60" width="16" height="120" fill="#fffdf5" stroke="#547970"/><rect data-lever-force x="700" y="${180-10*v.force}" width="16" height="${10*v.force}" fill="#397958"/><path data-lever-limit d="M690 ${180-10*v.job.capacity}H734" stroke="#b2572e" stroke-width="3"/>${[0,6,12].map(t=>`<text x="685" y="${185-10*t}" text-anchor="end">${t}</text>`).join('')}</g></svg>`;}
function instruction(v){return v.planned?'Find a pivot place that fits this delivery. Sometimes more than one works.':v.done?'Delivery reached the top mark.':'Push down one meter at a time. Watch the load rise.';}
export function leverComparison(v,held){const current=v.planned?'Current planned lever':'Current lever',role=v.planned?'current planned':'current';if(!held)return 'Keep a completed trip, then try another machine or plan.';if(held.kind!=='lever')return `${current}: ${v.force} N vertically down ${v.pivot} m. Held ramp: ${held.weight/held.length} N along ${held.length} m of rope. ${v.job.weight===held.weight?'Same load and 1 m rise. Calculated whole-trip work is the same, although the machines move differently.':'Both the load and machine changed; their whole-trip work differs.'}`;if(v.job.weight===held.weight&&v.pivot===held.drop)return 'The load and pivot setting are the same.';if(v.job.weight===held.weight)return `Same load and target rise. The ${v.pivot>held.drop?role:'held'} trip has the longer push arm: less vertical force, more vertical drop. Whole-trip work stays the same.`;if(v.pivot===held.drop)return `Same pivot and rise. The ${v.job.weight>held.weight?'current':'held'} load is heavier: it needs more force and more whole-trip work.`;return 'Both load weight and pivot setting changed. Compare the numbers; this does not isolate the effect of pivot position.';}
function notice(v){if(v.work.notice==='space')return `This setup needs ${v.arms.push} m on the push side. This delivery has ${v.job.space} m. Choose a setting that fits.${v.work.started?' Your current trip is still waiting.':''}`;if(v.work.notice==='force')return `This setting needs ${v.force} N. This push unit can provide up to ${v.job.capacity} N. Try a longer push arm that fits.${v.work.started?' Your current trip is still waiting.':''}`;return '';}
function controls(v,held){const w=v.work,active=leverArms(w.pivot),different=w.started&&w.draft!==w.pivot,waiting=`${active.push} m push arm / ${active.load} m load arm`;
 if(v.planned)return `<p class="ll-key-label">Push arm / load arm, along the pole</p><div class="ll-pivots" role="group" aria-label="Push arm / load arm, measured along the pole">${leverPivots.map((r,i)=>{const a=leverArms(r);return `<button type="button" data-lever-action="pivot" data-lever-value="${r}" aria-pressed="${v.pivot===r}" aria-label="${['Middle','Nearer load','Nearest load'][i]}: ${a.push} / ${a.load} m, push arm ${a.push} meters, load arm ${a.load} meters"><span>${['Middle','Nearer load','Nearest load'][i]}</span><strong>${a.push} / ${a.load} m</strong></button>`;}).join('')}</div><p class="ly-preview">${v.arms.push} m push arm · ${v.arms.load} m load arm · needs ${v.force} N downwards${!v.space?' · Planned setup—its push side needs more space than this delivery provides.':!v.capacity&&!w.notice?' · Planned setup—needs more push than this unit provides.':''}</p>${different?`<p>Your ${waiting} trip waits at ${w.drop} of ${w.pivot} m pushed down. This preview starts at the bottom.</p>${v.space&&v.capacity?`<p>Starting this setup ends your waiting ${waiting} trip.${w.delivered?' Your earlier delivery stays complete.':''}</p>`:''}`:''}<div class="ly-actions">${btn('start',w.started&&w.pivot===w.draft?'Continue this trip':different?'Start this setup from the bottom':'Start this setup',`class="ly-primary" ${w.notice?'aria-describedby="lever-notice"':''}`)}${different?btn('keep','Keep current trip'):''}</div>`;
 return `<p class="ll-active-arms">${v.arms.push} m push arm / ${v.arms.load} m load arm</p><div class="ly-actions">${btn('push','Push down 1 m',`class="ly-primary" ${v.done?'disabled':''}`)}${v.done?btn('next','Next delivery'):''}${btn('plan','Change plan')}</div><div class="ly-tools">${v.done?btn('hold',held?'Replace held trip':'Keep this trip'):''}${btn('bottom','Return load to start')}</div>${w.delivered?'<p>Repeating a delivery counts once for this lever shift. Returning the load keeps its earlier delivery complete.</p>':''}`;
}
function details(v,opened){return `<details data-lever-details="lever-model" ${opened['lever-model']?'open':''}><summary>About this model</summary><p>The pivot is the turning point. The arm on your side is the push arm; the other supports the load. The pole keeps its length. The push unit follows its end sideways, always pushing straight down. The pivot stays still while each end follows an arc.</p><p>We imagine very slow, controlled changes and ignore acceleration, pole weight, bending and friction. A brake holds each checkpoint. Our force numbers come from balance calculations, not a real force meter. Real lifting needs suitable equipment and trained people.</p><p>Space means the initial horizontal push-arm centreline span from the pivot, not a prediction about room for an operator's body. The guide is a projected span, not a wall.</p></details><details data-lever-details="lever-why" ${opened['lever-why']?'open':''}><summary>Why a longer push arm helps</summary><p>A 12 N load at the middle setting needs 12 N through 1 m downwards. At the nearer-load setting, it needs 6 N through 2 m downwards. Both raise the load 1 m and put in 12 J of work. The longer push arm trades less force for more vertical movement.</p></details><details data-lever-details="lever-path" ${opened['lever-path']?'open':''}><summary>Why not measure the curved path?</summary><p>Our push points straight down, so only the downward part of its movement counts in that push's work. The end moves sideways too. Multiplying this vertical force by the whole curved path would give the wrong answer.</p></details><details data-lever-details="lever-sources" ${opened['lever-sources']?'open':''}><summary>Grown-ups: sources and limits</summary><p>This is a supplied quasi-static model, not a dynamic speed simulation, physical experiment or assessment. The pole is treated as rigid and weightless. We balance turning effects at each position and imagine a controlled transition, rather than claiming balanced torques start motion by themselves. The stationary pivot does no work. Ideal input work equals load–Earth gravitational potential energy gain. Real machines have additional losses and weight. No actions, help requests, reading or hearing results are recorded.</p><p>Required vertical push = weight × load arm ÷ push arm. Whole-trip input work ${v.force} N × ${v.pivot} m = ${v.fullWork} J. Potential energy gain so far: ${v.job.weight} N × ${fraction(v.drop,v.pivot)} m = ${v.job.weight*v.rise} J. Newtons measure force, not mass.</p><p><a href="https://openstax.org/books/physics/pages/9-3-simple-machines" target="_blank" rel="noopener noreferrer">OpenStax: simple machines</a> · <a href="https://openstax.org/books/physics/pages/9-1-work-power-and-the-work-energy-theorem" target="_blank" rel="noopener noreferrer">work</a> · <a href="https://openstax.org/books/university-physics-volume-1/pages/10-6-torque" target="_blank" rel="noopener noreferrer">torque</a> · <a href="https://openstax.org/books/university-physics-volume-1/pages/12-1-conditions-for-static-equilibrium" target="_blank" rel="noopener noreferrer">static equilibrium</a></p></details>`;}
export function leverYardPage(local,{destinations,workPicture,heldPanel,heldText,modes}){const s=local.lever,shared=local.model,v=leverView(s),held=shared.held,hear=`${destinations[s.current]}. ${v.planned?'Current planned lever':'Current lever'}. Load weight ${v.job.weight} newtons. Push-unit limit ${v.job.capacity} newtons. Space from the pivot for the push side ${v.job.space} meters. Push arm ${v.arms.push} meters, load arm ${v.arms.load} meters. ${instruction(v)} Required vertical push ${v.force} newtons. Vertical drop ${v.drop} of ${v.pivot} meters. Load rise ${fraction(v.drop,v.pivot)} meter. Input work so far ${v.energy} joules.${held?' '+heldText(held):''}`;
 const complete=v.count===6?`<aside class="ly-complete" role="status"><strong>All six lever deliveries reached the top mark. The stores are stocked for this lever shift!</strong>${btn('shift','Another lever shift')}<span>Another lever shift changes these six jobs. Your ramp jobs, view and held trip stay.</span></aside>`:'';
 const jobs=`<section class="ly-jobs"><h2>Six lever deliveries · ${v.count} reached the top</h2><p>Every lever job is open. Waiting trips stay where you left them.</p>${s.works.map((w,i)=>{const j=leverJob(s,i);return btn('job',`${destinations[i]} · ${j.weight} N · push unit ${j.capacity} N · space ${j.space} m${w.delivered?' · delivery complete':''}${w.started?` · current trip ${w.drop} of ${w.pivot} m pushed down`:''}`,`data-lever-value="${i}"`);}).join('')}${btn('return','Return to current lever job')}</section>`;
 const body=`<section class="ly-turn"><h2>${destinations[s.current]} <small>· ${v.planned?'Plan':'Push'}</small></h2><p class="ly-tag">Load weight: ${v.job.weight} N · Push unit can provide up to ${v.job.capacity} N · Space from the pivot for the push side: ${v.job.space} m · Pole: 12 m · Target rise: 1 m</p><figure class="ly-scene">${shared.representation==='yard'?leverDrawing(v):workPicture({job:v.job,length:v.pivot,distance:v.drop,force:v.force,energy:v.energy,planned:v.planned},held,'lever')}<figcaption>${shared.representation==='yard'?`Bar: required push ${v.force} N · line: limit ${v.job.capacity} N. Dotted curve: end path. Left bracket: vertical drop used for work. The pictures have different scales; compare work in Numbers. The space guide marks a starting span, not a wall.`:'Each fixed-size cell = 1 J. Filled columns show input work so far. Rectangles represent force × distance, not square meters.'}</figcaption></figure><div class="ly-console"><p class="ly-instruction" data-lever-instruction>${instruction(v)}</p>${controls(v,held)}<p class="ly-notice" id="lever-notice" role="status" tabindex="-1">${esc(notice(v))}</p></div><dl class="ly-facts"><div><dt>${v.planned?'Planned trip · vertical push drop':'Current trip · vertical push drop'}</dt><dd data-lever-distance>${v.drop} of ${v.pivot} m</dd></div><div><dt>Load rise</dt><dd>${fraction(v.drop,v.pivot)} m</dd></div><div><dt>Required vertical push</dt><dd>${v.force} N</dd></div><div><dt>Input work so far</dt><dd>${v.energy} J</dd></div></dl><p class="ly-whole">Whole trip: ${v.force} N × ${v.pivot} m vertically down = ${v.fullWork} J. At the bottom rise is 0 m; at the top, 1 m.</p><button type="button" data-speak="${esc(hear)}">Hear this turn</button></section>`;
 return `<section class="ly-room ly-lever" data-lift-root><header><a href="#workshop">← More workshop tables</a><p class="eyebrow">Willowbank · restocking the upper storeroom</p><h1 id="lift-title" tabindex="-1">The Lift Yard</h1><p>Try a lever for the upper storeroom. Push one end down to lift the other. Where will you put the pivot?</p></header><div class="ly-toolbar">${modes}<div role="group" aria-label="View">${['yard','numbers'].map(r=>btn('view',r==='yard'?'Yard':'Numbers',`data-lever-value="${r}" aria-pressed="${shared.representation===r}"`)).join('')}</div>${btn('jobs','Other lever deliveries')}</div>${complete}${s.page==='jobs'?jobs:body}${heldPanel(held,s.page==='work'?leverComparison(v,held):'','lever')}<p class="ly-local">Switching machines keeps both sets of waiting jobs, your view and one held completed trip. Leaving the yard or reloading starts fresh. Nothing here changes saved learning notes.</p>${details(v,local.details)}<a class="ly-exit" href="#workshop/fair">Compare cart landings</a></section>`;
}
let motion=null;
export function stopLeverMotion(){motion?.cancel();motion=null;}
function drawnDrop(root){const e=root.querySelector('[data-lever-handle]');return e?(+e.getAttribute('cy')-145)/40:null;}
function applyPose(root,g){const q=poseParts(g),attr=(selector,key,value)=>root.querySelector(selector)?.setAttribute(key,value);attr('[data-lever-pole]','points',q.pole);attr('[data-lever-centreline]','d',q.line);attr('[data-lever-handle]','cx',g.e.x);attr('[data-lever-handle]','cy',g.e.y);attr('[data-lever-hanger]','d',q.hanger);attr('[data-lever-load]','transform',`translate(${g.c.x} ${g.c.y})`);attr('[data-lever-push-arrow]','d',q.arrow);attr('[data-lever-end-path]','d',q.arc);attr('[data-lever-drop-bracket]','d',q.bracket);for(const [id,p]of[['push',g.pushLabel],['load',g.loadLabel]]){attr(`[data-lever-arm-label="${id}"]`,'x',p.x);attr(`[data-lever-arm-label="${id}"]`,'y',p.y);}}
function animate(root,from,r,to,live){if(!Number.isFinite(from)||!live()||typeof matchMedia!=='function'||matchMedia('(prefers-reduced-motion: reduce)').matches||typeof requestAnimationFrame!=='function')return;let frame=0,start=null,ended=false;const begin=Math.max(0,Math.min(r,from)),finish=leverGeometry(r,to),owned={cancel(){if(ended)return;ended=true;cancelAnimationFrame(frame);if(live())applyPose(root,finish);root.removeAttribute('data-lever-moving');}};motion=owned;root.setAttribute('data-lever-moving','true');applyPose(root,leverGeometry(r,begin));const tick=time=>{if(ended||!live()){owned.cancel();if(motion===owned)motion=null;return;}if(start===null)start=time;const t=Math.min(1,(time-start)/180),e=1-(1-t)**2;applyPose(root,leverGeometry(r,Math.max(0,Math.min(r,begin+(to-begin)*e))));if(t<1)frame=requestAnimationFrame(tick);else{ended=true;root.removeAttribute('data-lever-moving');if(motion===owned)motion=null;}};frame=requestAnimationFrame(tick);}
export function bindLeverYard(root,local,{owner,render,stopSpeech,stopSound,stopMotion}){const live=()=>owner()&&root.isConnected&&local.mode==='lever';root.querySelectorAll('[data-lever-details]').forEach(d=>d.addEventListener('toggle',()=>{if(live())local.details[d.dataset.leverDetails]=d.open;}));root.querySelectorAll('[data-lever-action]').forEach(b=>b.addEventListener('click',()=>{
 if(!live()||b.disabled)return;const a=b.dataset.leverAction,value=['pivot','job'].includes(a)?Number(b.dataset.leverValue):b.dataset.leverValue,v=leverView(local.lever),next=['view','hold','clear'].includes(a)?null:changeLever(local.lever,a,value);let shared=null;
 if(a==='view'&&['yard','numbers'].includes(value))shared={...local.model,representation:value};else if(a==='hold'&&v.done)shared={...local.model,held:{kind:'lever',weight:v.job.weight,drop:v.work.pivot}};else if(a==='clear')shared={...local.model,held:null};else if(!next)return;
 const from=a==='push'&&local.model.representation==='yard'?drawnDrop(root):null;stopSpeech();stopSound();stopMotion();for(const d of root.querySelectorAll('[data-lever-details]'))local.details[d.dataset.leverDetails]=d.open;if(shared)local.model=shared;if(next)local.lever=next;render();
 const newRoot=document.querySelector('[data-lift-root]'),newLive=()=>owner()&&newRoot?.isConnected&&local.mode==='lever';if(!newLive())return;const after=leverView(local.lever);if(from!==null)animate(newRoot,from,after.work.pivot,after.work.drop,newLive);
 let target=newRoot.querySelector(`[data-lever-action="${a}"]${['pivot','job','view'].includes(a)?`[data-lever-value="${value}"]`:''}`);if(a==='start'||a==='keep')target=after.work.notice?newRoot.querySelector('#lever-notice'):newRoot.querySelector('[data-lever-action="push"]')||target;if(a==='plan')target=newRoot.querySelector(`[data-lever-action="pivot"][data-lever-value="${after.work.draft}"]`);if(a==='jobs')target=newRoot.querySelector(after.count===6?'[data-lever-action="shift"]':`[data-lever-action="job"][data-lever-value="${local.lever.current}"]`);if(['next','job','return','shift'].includes(a))target=newRoot.querySelector('[data-lever-action="start"],[data-lever-action="push"],[data-lever-action="return"]');if(a==='clear')target=newRoot.querySelector('[data-lever-action="hold"],[data-lever-action="start"],[data-lever-action="push"]:not(:disabled),[data-lever-action="return"]');if(target?.disabled)target=newRoot.querySelector('[data-lever-action="next"]');(target||newRoot.querySelector('#lift-title'))?.focus();
 }));}
